import{_ as s,o as i,c as a,ao as e}from"./chunks/framework.CKOtou8s.js";const c=JSON.parse('{"title":"1D and 2D meshes","description":"","frontmatter":{},"headers":[],"relativePath":"data/mesh2d.md","filePath":"data/mesh2d.md","lastUpdated":null}'),h={name:"data/mesh2d.md"};function l(n,t,d,o,p,r){return i(),a("div",null,[...t[0]||(t[0]=[e(`<h1 id="1D-and-2D-meshes" tabindex="-1">1D and 2D meshes <a class="header-anchor" href="#1D-and-2D-meshes" aria-label="Permalink to &quot;1D and 2D meshes {#1D-and-2D-meshes}&quot;">​</a></h1><p>Before we can model or invert data we need a mesh: the cells in which the resistivity is defined. A good mesh is fine near the stations and at shallow depth, where the data see the most detail, and coarse far away. In this section we build meshes directly from a data file.</p><h2 id="1D:-nothing-to-do" tabindex="-1">1D: nothing to do <a class="header-anchor" href="#1D:-nothing-to-do" aria-label="Permalink to &quot;1D: nothing to do {#1D:-nothing-to-do}&quot;">​</a></h2><p>A 1D inversion builds its own layering for every site, so usually you do not need this step. <code>MakeMesh1D</code> makes layers that start thin at the surface (a fifth of the skin depth at the highest frequency) and grow with depth. You can call it yourself to change the settings:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">meshes </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> MakeMesh1D</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">load_data2d</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;data.dat&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">); first_layer_div </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, vertical_factor </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1.1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, depth_mult </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 4</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><h2 id="Build-a-2D-mesh" tabindex="-1">Build a 2D mesh <a class="header-anchor" href="#Build-a-2D-mesh" aria-label="Permalink to &quot;Build a 2D mesh {#Build-a-2D-mesh}&quot;">​</a></h2><p><code>MakeMesh2D</code> reads a data file and writes everything a 2D inversion needs:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/make_mesh2D.jl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> data.dat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> topo.dat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> out_dir</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # opens a window</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/make_mesh2D.jl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> data.dat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> topo.dat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> out_dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> batch</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # no window</span></span></code></pre></div><p>or, from Julia:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">MakeMesh2D</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;data.dat&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; out_dir </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;mesh&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, topo_path </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;topo.dat&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, mode </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> :batch</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>In <code>out_dir</code> you will find:</p><ul><li><p><code>model.start</code> and <code>model.prior</code>: the start and reference models</p></li><li><p><code>fwd.ctrl</code>, <code>inv.ctrl</code>, <code>cov.ctrl</code>: the inputs of <a href="./../inversion/2d_deterministic">Gauss–Newton and NLCG</a></p></li><li><p><code>vfsa.ctrl</code>, <code>mask.ctrl</code>: the inputs of <a href="./../inversion/2d_vfsa">VFSA</a></p></li><li><p>the data rotated to the strike, <code>data-r.dat</code></p></li><li><p><code>Mesh.png</code> and <code>MeshCore.png</code>: pictures of the whole mesh and of its core</p></li></ul><p>The tool also prints a summary with advice, for example when two stations share a cell or when the padding is shorter than the skin depth at the lowest frequency.</p><p>With <code>mode = :gui</code> every setting is a slider with a live preview. <strong>Save inputs</strong> writes the files.</p><h2 id="The-main-settings" tabindex="-1">The main settings <a class="header-anchor" href="#The-main-settings" aria-label="Permalink to &quot;The main settings {#The-main-settings}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Setting</th><th style="text-align:left;">Default</th><th style="text-align:left;">Meaning</th></tr></thead><tbody><tr><td style="text-align:left;"><code>cell_width_frac</code></td><td style="text-align:left;">0.5</td><td style="text-align:left;">core cell width, as a fraction of the station spacing</td></tr><tr><td style="text-align:left;"><code>n_pad</code>, <code>pad_factor</code></td><td style="text-align:left;">12, 1.3</td><td style="text-align:left;">number of padding cells on each side, and their growth</td></tr><tr><td style="text-align:left;"><code>first_layer_div</code></td><td style="text-align:left;">5</td><td style="text-align:left;">first layer = skin depth at the highest frequency / this</td></tr><tr><td style="text-align:left;"><code>vertical_factor</code></td><td style="text-align:left;">1.1</td><td style="text-align:left;">growth of the layers with depth</td></tr><tr><td style="text-align:left;"><code>depth_mult</code></td><td style="text-align:left;">4</td><td style="text-align:left;">model depth = this × skin depth at the lowest frequency</td></tr><tr><td style="text-align:left;"><code>strike</code></td><td style="text-align:left;"><code>nothing</code></td><td style="text-align:left;"><code>nothing</code> estimates it from the data; or degrees clockwise from north</td></tr></tbody></table><p>All settings are listed in the <a href="./../developers/control_files">control file reference</a>.</p><h2 id="Topography-and-water" tabindex="-1">Topography and water <a class="header-anchor" href="#Topography-and-water" aria-label="Permalink to &quot;Topography and water {#Topography-and-water}&quot;">​</a></h2><p>Give <code>MakeMesh2D</code> a <code>topo.dat</code> and it cuts the ground surface into the mesh. <code>topo.dat</code> holds WGS84 <code>lat lon elevation</code> points along the line, in metres above sea level. Where there is a lake or sea, give the elevation of its bottom and mark the water:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">MakeMesh2D</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;data.dat&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; out_dir </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;mesh&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, topo_path </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;topo.dat&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">           water </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [(y_range </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5500.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2500.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">), level </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 100.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)], water_resistivity </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 200.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>Here a lake lies between −5.5 and −2.5 km along the profile, with its surface at 100 m. The tool places every station on the ground of its column, and the depths in the data file (Z) are set to match.</p><h2 id="Masks" tabindex="-1">Masks <a class="header-anchor" href="#Masks" aria-label="Permalink to &quot;Masks {#Masks}&quot;">​</a></h2><p>The mask says which cells the inversion may change. Gauss–Newton and NLCG read it from <code>cov.ctrl</code>, VFSA from <code>mask.ctrl</code>. Both hold the same values:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Value</th><th style="text-align:left;">Cells</th></tr></thead><tbody><tr><td style="text-align:left;">0</td><td style="text-align:left;">air, or cells you want to keep fixed</td></tr><tr><td style="text-align:left;">9</td><td style="text-align:left;">water: fixed, and not smoothed across</td></tr><tr><td style="text-align:left;">any other</td><td style="text-align:left;">free</td></tr></tbody></table><p>You can build a mask yourself, for example to fix everything below 30 km:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mask </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Mask2D</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">ReadModel2D</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;model.start&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">); fixed_below_m </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 30e3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">WriteMask2D</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;mask.ctrl&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, mask)</span></span></code></pre></div>`,26)])])}const g=s(h,[["render",l]]);export{c as __pageData,g as default};
